    pub(crate) fn as_static_str(&self) -> Option<&'static str> {
        Self::STATIC_CODE_LIST.get(self.as_enum_tag()).copied()
    }

    #[must_use]
    pub fn from_bytes(s: &[u8]) -> Option<Self> {
        let s = std::str::from_utf8(s).ok()?;
        if let Some(code) = S3_ERROR_CODE_MAP.get(s) {
            return Some(code.clone());
        }
        let lowercase = s.to_ascii_lowercase();
        if let Some(code) = S3_ERROR_CODE_LOWERCASE_MAP.get(lowercase.as_str()) {
            return Some(code.clone());
        }
        Some(Self::Custom(s.into()))
    }

